package com.example.Lifepath.service;
import com.example.Lifepath.dto.AuthDtos.*; import com.example.Lifepath.entity.*; import com.example.Lifepath.exception.ApiException; import com.example.Lifepath.repository.*; import com.example.Lifepath.security.JwtService; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService {private final UserRepository users;private final UserProfileRepository profiles;private final PasswordEncoder encoder;private final JwtService jwt;public AuthService(UserRepository u,UserProfileRepository p,PasswordEncoder e,JwtService j){users=u;profiles=p;encoder=e;jwt=j;} @Transactional public UserView register(Register r){if(users.existsByEmail(r.email()))throw new ApiException(HttpStatus.CONFLICT,"Email already registered");User u=users.save(new User(r.name(),r.email().toLowerCase(),encoder.encode(r.password())));profiles.save(new UserProfile(u));return view(u);} public AuthResponse login(Login r){User u=users.findByEmail(r.email().toLowerCase()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!encoder.matches(r.password(),u.getPassword()))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return new AuthResponse(jwt.create(u),view(u));}public UserView currentUser(Long id){return view(users.findById(id).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Authenticated user no longer exists")));}private UserView view(User u){return new UserView(u.getId(),u.getName(),u.getEmail(),u.getRole().name());}}
